I use LockManager to shim web-worker onclose.

A work-around, if you're able to re-jigger your use-case to use Streams instead of MessagePort

```js
let { readable, writable } = new TransformStream(); // fundamental stream pair

const canary_transform = new TransformStream(); // hack to detect when fundamental stream pair is closed -- workaround https://github.com/whatwg/html/issues/1766
const canary = readable.pipeTo(canary_transform.writable);
readable = canary_transform.readable;

TARGET.postMessage({ replyStream: writable }, { transfer: [writable] });
canary.finally(CLEANUP_HOOK);
USE_STREAM(readable);
```

@fergald Sure, here's a quick demo: https://webpages.uah.edu/~je0029/tmp/demo_stream_canary/

The stream-pair workaround as described above is found on line 33 of _helper\.html_; it prints “Stream cleanup handler called.” to the debug console in a _finally_ handler on the canary transform that's injected before transferring out the stream pair.

I found this to trigger (at least on Firefox) regardless of whether the stream was ended from the _writable_ end (my test transfers that to its parent frame, and I confirmed it works even when that parent frame is on a different origin, such as `http://localhost`) or from the _readable_ end (my test transfers thatto a serviceworker).

My use case is to host centralized client-side state within a `SharedWorker` and broadcast changes to all connected clients to facilitate cross-tab synchronization.

Below is a trivial example that describes the case

<details>
<summary>Minimal example code</summary>

```html
<!-- index.html -->
<body>
  <div id="count"></div>
  <button id="increment">Increment</button>
</body>
<script type="module">
  const elm_div_count = document.getElementById('count')
  const elm_btn_increment = document.getElementById('increment')

  const worker = new SharedWorker('./worker.mjs', { type: "module" })

  worker.port.addEventListener('message', (e) => {
    elm_div_count.innerHTML = e.data
  })

  elm_btn_increment.addEventListener('click', () => {
    worker.port.postMessage(null)
  })

  worker.port.start()
</script>
```

```javascript
// worker.js
/** @type {Array<MessagePort>} */
const ports = []

let count = 0;

globalThis.onconnect = e => {
  const [port] = e.ports
  console.log('connected')

  port.addEventListener('message', (e) => {
    count += 1
    for (const port of ports) port.postMessage(count)
  })

  ports.push(port)
  port.postMessage(count)
  port.start()
}
```

</details>

My real use case is a complex SPA (Jira) that needs cross-tab synchronization. It's important to have the ability to _reliably_ clean up ports within the worker to avoid the accumulation of dead ports as users open/close tabs throughout their session.

Even something as simple as a returning a `boolean` from `MessagePort.postMessage(): boolean` would allow me to manually detect if a MessagePort has closed from the worker and clean it up if `false` is returned.

The current solutions are:
- Using the `beforeunload` event to notify the worker of a disconnection
    - This is unreliable
- Having the client send an ack response and removing the port if it isn't detected
    - This is overly chatty and the web is a resource constrained environment
- Sending periodic "keepalive" health check events
    - May adversely affect battery life and/or be affected by browser  optimizations like page discarding (temporary suspend)
- Using the locks API
    - Can be used but is verbose

It would be very helpful if there was a reliable means to determine when a client disconnects from a `SharedWorker`

For reference, this is my current solution I'm experimenting with using locks

<details>
<summary>Locks example code</summary>

```javascript
// lib.mjs
// For clients to connect
export class TrackedSharedWorker extends EventTarget {
  #port;

  constructor(...args) {
    super();

    const id = crypto.randomUUID();
    const worker = new SharedWorker(...args);

    navigator.locks.request(id, async (_lock) => {
      worker.port.postMessage(id);
      worker.port.start();
      // Never resolve to hold the lock until page close
      await new Promise(() => {});
    });

    this.#port = worker.port;
  }

  postMessage(...args) {
    return this.#port.postMessage(...args);
  }

  addEventListener(...args) {
    return this.#port.addEventListener(...args);
  }

  removeEventListener(...args) {
    return this.#port.removeEventListener(...args);
  }
}

// Used by SharedWorkers to interact with the parent 
export class Connection extends EventTarget {
  #port;
  #id;

  constructor(port, id) {
    super();

    navigator.locks.request(id, (_lock) => {
      this.#port.dispatchEvent(new Event("disconnect"));
    });

    this.#port = port;
    this.#id = id;
  }

  id() {
    return this.#id;
  }

  postMessage(...args) {
    return this.#port.postMessage(...args);
  }

  addEventListener(...args) {
    return this.#port.addEventListener(...args);
  }

  removeEventListener(...args) {
    return this.#port.removeEventListener(...args);
  }
}

export class ConnectionManager extends EventTarget {
  /** @type {Set<Connection>} */
  #connections;

  constructor() {
    super();
    this.#connections = new Set();

    globalThis.addEventListener("connect", async (event) => {
      const port = event.ports[0];

      const onReady = new Promise((res) =>
        port.addEventListener("message", res, { once: true })
      );

      port.start();
      const { data: id } = await onReady;

      const conn = new Connection(port, id);

      conn.addEventListener("disconnect", 
        () => this.#connections.delete(conn),
        { once: true }
      );

      this.#connections.add(conn);
      this.dispatchEvent(new MessageEvent("connect", { data: conn }));
    });
  }

  getConnections() {
    return this.#connections.values();
  }

  postMessageAll(...args) {
    for (const conn of this.getConnections()) {
      conn.postMessage(...args);
    }
  }
}
```

```html
<!-- index.html -->
<body>
  <div id="count"></div>
  <button id="increment">Increment</button>
</body>
<script type="module">
  import { TrackedSharedWorker } from './lib.mjs'

  const elm_div_count = document.getElementById('count')
  const elm_btn_increment = document.getElementById('increment')

  const worker = new TrackedSharedWorker('./worker.mjs', { type: "module" })

  worker.addEventListener('message', (e) => {
    elm_div_count.innerHTML = e.data
  })

  elm_btn_increment.addEventListener('click', () => {
    worker.postMessage(null)
  })
</script>
```

```javascript
// worker.mjs
import { ConnectionManager } from "./lib.mjs";

// Shared state
let count = 0;

const worker = new ConnectionManager();

worker.addEventListener("connect", ({ data: conn }) => {
  console.log("Connected", conn.id());

  conn.postMessage(count);

  conn.addEventListener("message", (_e) => {
    count += 1;
    worker.postMessageAll(count);
  });

  conn.addEventListener("disconnect", (_e) => 
    console.log("Disconnected", conn.id()),
    { once: true }
  );
});
```

